-- Official menu catalog. Additive: existing menu_products and price_customer_order remain intact.
-- Seed data is appended from data/menu-catalog.json by scripts/build-menu-sql.cjs.
begin;

create table public.menu_catalog (
  id text primary key check (id ~ '^[a-z0-9-]{1,120}$'),
  name text not null check (length(trim(name)) between 1 and 120),
  category text not null check (length(trim(category)) between 1 and 60),
  description text not null default '' check (length(description) <= 500),
  icon text not null default 'cup',
  image_url text check (image_url is null or image_url ~ '^https://[^[:space:]]+$' or image_url ~ '^/assets/[^[:space:]]+$'),
  featured boolean not null default false,
  customizable boolean not null default false,
  variant_label text not null default 'Size' check (length(trim(variant_label)) between 1 and 60),
  active boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);

create table public.menu_catalog_variants (
  product_id text not null references public.menu_catalog(id) on delete cascade,
  id text not null check (id ~ '^[a-z0-9-]{1,80}$'),
  label text not null check (length(trim(label)) between 1 and 100),
  price numeric(12,2) not null check (price between 0 and 100000),
  active boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  primary key (product_id, id)
);

create table public.menu_catalog_addons (
  product_id text not null references public.menu_catalog(id) on delete cascade,
  id text not null check (id ~ '^[a-z0-9-]{1,80}$'),
  label text not null check (length(trim(label)) between 1 and 100),
  price numeric(12,2) not null check (price between 0 and 100000),
  active boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  primary key (product_id, id)
);

alter table public.menu_catalog enable row level security;
alter table public.menu_catalog_variants enable row level security;
alter table public.menu_catalog_addons enable row level security;
revoke all on public.menu_catalog, public.menu_catalog_variants, public.menu_catalog_addons from anon, authenticated;
grant select on public.menu_catalog, public.menu_catalog_variants, public.menu_catalog_addons to anon, authenticated;
grant insert, update on public.menu_catalog, public.menu_catalog_variants, public.menu_catalog_addons to authenticated;
grant all on public.menu_catalog, public.menu_catalog_variants, public.menu_catalog_addons to service_role;
revoke delete on public.menu_catalog, public.menu_catalog_variants, public.menu_catalog_addons from anon, authenticated;

create policy "Public active menu" on public.menu_catalog for select to anon, authenticated
using (active or (select public.can_manage_orders()));
create policy "Managers add menu" on public.menu_catalog for insert to authenticated
with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));
create policy "Managers edit menu" on public.menu_catalog for update to authenticated
using ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false)) with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));

create policy "Public active variants" on public.menu_catalog_variants for select to anon, authenticated
using ((active and exists (select 1 from public.menu_catalog p where p.id = product_id and p.active)) or (select public.can_manage_orders()));
create policy "Managers add variants" on public.menu_catalog_variants for insert to authenticated
with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));
create policy "Managers edit variants" on public.menu_catalog_variants for update to authenticated
using ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false)) with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));

create policy "Public active extras" on public.menu_catalog_addons for select to anon, authenticated
using ((active and exists (select 1 from public.menu_catalog p where p.id = product_id and p.active)) or (select public.can_manage_orders()));
create policy "Managers add extras" on public.menu_catalog_addons for insert to authenticated
with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));
create policy "Managers edit extras" on public.menu_catalog_addons for update to authenticated
using ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false)) with check ((select public.can_manage_orders()) and not coalesce((select (auth.jwt() ->> 'is_anonymous')::boolean), false));

create function public.touch_menu_catalog_updated_at() returns trigger
language plpgsql security invoker set search_path = '' as $$
begin new.updated_at = now(); return new; end;
$$;
revoke all on function public.touch_menu_catalog_updated_at() from public, anon, authenticated;
create trigger menu_catalog_updated before update on public.menu_catalog for each row execute function public.touch_menu_catalog_updated_at();
create trigger menu_variants_updated before update on public.menu_catalog_variants for each row execute function public.touch_menu_catalog_updated_at();
create trigger menu_addons_updated before update on public.menu_catalog_addons for each row execute function public.touch_menu_catalog_updated_at();

create function public.price_catalog_order(raw_items jsonb) returns jsonb
language plpgsql stable security invoker set search_path = '' as $$
declare
  line jsonb; product public.menu_catalog%rowtype; variant public.menu_catalog_variants%rowtype;
  extra public.menu_catalog_addons%rowtype; extra_id jsonb; extra_ids jsonb;
  quantity integer; sugar_id text; ice_id text; sugar_label text; ice_label text;
  extras jsonb; items jsonb := '[]'; unit_price numeric; total numeric := 0;
begin
  if raw_items is null or jsonb_typeof(raw_items) <> 'array' then raise exception 'Items must be an array'; end if;
  if jsonb_array_length(raw_items) not between 1 and 50 then raise exception 'Choose between 1 and 50 order lines'; end if;
  for line in select value from jsonb_array_elements(raw_items) loop
    if jsonb_typeof(line) <> 'object' or jsonb_typeof(line->'quantity') is distinct from 'number'
      or coalesce(line->>'quantity', '') !~ '^[0-9]{1,2}$' then raise exception 'Invalid quantity'; end if;
    quantity := (line->>'quantity')::integer;
    if quantity not between 1 and 20 then raise exception 'Quantity must be between 1 and 20'; end if;
    select * into product from public.menu_catalog where id = line->>'product_id' and active;
    if not found then raise exception 'Menu item is unavailable'; end if;
    select * into variant from public.menu_catalog_variants where product_id = product.id and id = line->>'size_id' and active;
    if not found then raise exception 'Size or serving is unavailable'; end if;
    sugar_id := line->>'sugar_id'; ice_id := line->>'ice_id';
    if product.customizable then
      if sugar_id is null or sugar_id not in ('less-sugar','more-sugar','original-recipe','0','25','50','75','100') then raise exception 'Invalid sugar level'; end if;
      if ice_id is null or ice_id not in ('no-ice','less-ice','regular-ice','extra-ice') then raise exception 'Invalid ice level'; end if;
      sugar_label := case sugar_id when 'less-sugar' then 'Less sugar' when 'more-sugar' then 'More sugar' when 'original-recipe' then 'Original recipe' else sugar_id || '%' end;
      ice_label := case ice_id when 'no-ice' then 'No ice' when 'less-ice' then 'Less' when 'regular-ice' then 'Regular' else 'Extra' end;
    else
      if sugar_id is distinct from 'standard' or ice_id is distinct from 'not-applicable' then raise exception 'This item has no sugar or ice customization'; end if;
      sugar_label := 'Standard'; ice_label := 'Not applicable';
    end if;
    extra_ids := coalesce(line->'addon_ids', '[]'::jsonb);
    if jsonb_typeof(extra_ids) <> 'array' then raise exception 'Invalid extras'; end if;
    if jsonb_array_length(extra_ids) > 10 or jsonb_array_length(extra_ids) <> (select count(distinct value) from jsonb_array_elements(extra_ids)) then raise exception 'Duplicate or excessive extras'; end if;
    extras := '[]'; unit_price := variant.price;
    for extra_id in select value from jsonb_array_elements(extra_ids) loop
      if jsonb_typeof(extra_id) <> 'string' then raise exception 'Invalid extra'; end if;
      select * into extra from public.menu_catalog_addons where product_id = product.id and id = extra_id #>> '{}' and active;
      if not found then raise exception 'Extra is unavailable for this item'; end if;
      unit_price := unit_price + extra.price;
      extras := extras || jsonb_build_array(jsonb_build_object('id',extra.id,'label',extra.label,'price',extra.price));
    end loop;
    total := total + unit_price * quantity;
    items := items || jsonb_build_array(jsonb_build_object(
      'product_id',product.id,'name',product.name,'category',product.category,
      'size',jsonb_build_object('id',variant.id,'label',variant.label,'price',variant.price,'surcharge',0),
      'sugar',jsonb_build_object('id',sugar_id,'label',sugar_label),
      'ice',jsonb_build_object('id',ice_id,'label',ice_label),
      'addons',extras,'unit_price',unit_price,'quantity',quantity,'line_total',unit_price * quantity));
  end loop;
  return jsonb_build_object('items',items,'total_price',total);
end;
$$;
-- Called only by the verified-order server API; browser users cannot submit a total.
revoke all on function public.price_catalog_order(jsonb) from public, anon, authenticated;
grant execute on function public.price_catalog_order(jsonb) to service_role;

