insert into public.menu_catalog (id,name,category,description,icon,image_url,featured,customizable,variant_label,active,sort_order)
select p.id,p.name,p.category,p.description,p.icon,p.image_url,p.featured,p.customizable,p.variant_label,p.active,p.sort_order
from official_menu_seed s, jsonb_to_recordset(s.data) as p(id text,name text,category text,description text,icon text,image_url text,featured boolean,customizable boolean,variant_label text,active boolean,sort_order integer);

insert into public.menu_catalog_variants(product_id,id,label,price,sort_order)
select p->>'id',v->>'id',v->>'label',(v->>'price')::numeric,(n-1)::integer
from official_menu_seed s, jsonb_array_elements(s.data) p, jsonb_array_elements(p->'variants') with ordinality as options(v,n);

insert into public.menu_catalog_addons(product_id,id,label,price,sort_order)
select p->>'id',a->>'id',a->>'label',(a->>'price')::numeric,(n-1)::integer
from official_menu_seed s, jsonb_array_elements(s.data) p, jsonb_array_elements(p->'addons') with ordinality as options(a,n);

commit;
